#!/usr/bin/env bashset -euo pipefail# Install/verify the passive APRS digipeater survey already present in the ROC# checkout. This feature is part of n0jcg-roc.service; it never enables RF TX.SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"PROJECT_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"ROC_PORT="${ROC_PORT:-8095}"MODE=installcase "${1:-}" in  --check-only) MODE=check ;;  --no-restart) MODE=no-restart ;;  '') ;;  *)    echo 'Usage: install_aprs_digipeater_survey.sh [--check-only|--no-restart]'    exit 2    ;;esacfor required in \  src/n0jcg_roc/server.py \  web/index.html \  web/app.js \  web/styles.css \  docs/APRS_DIGIPEATER_SURVEY.md \  docs/N0JCG_Gateway_End_User_Guide_v0.1.2.md \  deploy/n0jcg-roc.service; do  [[ -f "${PROJECT_DIR}/${required}" ]] || {    echo "FINAL: FAIL - missing ${required}"    exit 1  }donePYTHONPATH="${PROJECT_DIR}/src" python3 -m unittest tests.test_server -qpython3 -m compileall -q "${PROJECT_DIR}/src"if [[ "${MODE}" == check ]]; then  echo 'FINAL: PASS - passive digipeater survey preflight only; no files changed'  exit 0fiif [[ "${MODE}" == install ]]; then  sudo systemctl daemon-reload  sudo systemctl enable n0jcg-roc.service >/dev/null  sudo systemctl restart n0jcg-roc.servicefisystemctl is-active --quiet n0jcg-roc.servicecurl --fail --silent --show-error "http://127.0.0.1:${ROC_PORT}/api/aprs/digipeaters" >/dev/nullecho 'FINAL: PASS - passive APRS digipeater survey is installed and responding'